using Yanmt.Core.Maps;

namespace Yanmt.Infrastructure.Data.Entities;

/// <summary>A hand-built map. Submaps are ordinary maps that another map links to through a submap element.</summary>
public class Map : IAudited
{
    public int Id { get; set; }
    public required string Name { get; set; }

    /// <summary>The map this one was created from, for breadcrumbs. Null for top-level maps.</summary>
    public int? ParentMapId { get; set; }
    public Map? ParentMap { get; set; }

    /// <summary>File name of the background image in the data folder's maps directory (generated by YANMT).</summary>
    public string? BackgroundImage { get; set; }

    public int Width { get; set; } = MapRules.DefaultWidth;
    public int Height { get; set; } = MapRules.DefaultHeight;

    public DateTime CreatedUtc { get; set; }
    public DateTime UpdatedUtc { get; set; }

    public List<MapElement> Elements { get; set; } = [];
    public List<MapLink> Links { get; set; } = [];
}

public enum MapElementKind
{
    Node,
    Submap,
}

/// <summary>A node or submap icon placed on a map. X/Y are the icon's centre in canvas pixels.</summary>
public class MapElement : IAudited
{
    public int Id { get; set; }
    public int MapId { get; set; }
    public Map Map { get; set; } = null!;
    public MapElementKind Kind { get; set; }

    public int? NodeId { get; set; }
    public Node? Node { get; set; }

    public int? TargetMapId { get; set; }
    public Map? TargetMap { get; set; }

    public double X { get; set; }
    public double Y { get; set; }

    /// <summary>Optional status source whose value is shown under the hostname (e.g. ICMP latency).</summary>
    public StatusSourceType? LabelSourceType { get; set; }

    public string? LabelSourceKey { get; set; }
}

/// <summary>A line between two elements on the same map, optionally bound to a monitor instance for its color.</summary>
public class MapLink : IAudited
{
    public int Id { get; set; }
    public int MapId { get; set; }
    public Map Map { get; set; } = null!;
    public int FromElementId { get; set; }
    public MapElement From { get; set; } = null!;
    public int ToElementId { get; set; }
    public MapElement To { get; set; } = null!;
    public string? Label { get; set; }

    /// <summary>The monitor instance (normally an interface) whose state colors the link. Null: neutral.</summary>
    public int? BoundMonitorInstanceId { get; set; }

    public MonitorInstance? BoundMonitorInstance { get; set; }

    /// <summary>Show the bound instance's current value next to the label.</summary>
    public bool ShowBoundValue { get; set; }
}
